package com.eec.bookhub.repository; import com.eec.bookhub.model.BorrowRequest; import org.springframework.data.jpa.repository.JpaRepository; import java.util.List; public interface BorrowRequestRepository extends JpaRepository<BorrowRequest,String>{ List<BorrowRequest> findByBorrowerIdOrProviderIdOrderByRequestDateDesc(String borrowerId,String providerId); boolean existsByBookIdAndBorrowerIdAndStatus(String bookId,String borrowerId,String status); }
